function _wrapKindNameOf(entry: unknown): string | undefined {
	if (!entry || typeof entry !== 'object') return undefined;
	const raw = (entry as { $type?: unknown }).$type;
	if (raw === undefined) return undefined;
	if (typeof raw === 'number') return KIND_NAMES.get(raw as never) ?? String(raw);
	return typeof raw === 'string' ? raw : undefined;
}

// The model is the wire contract: a `_<key>` the model has no slot for
// (a reference to a literal — the grammar-agnostic reader still emits it)
// never enters a wrapped node.
function _keepModelledSlots<T extends object>(data: T, keys: readonly string[]): T {
	const out: Record<string, unknown> = {};
	for (const key of Object.keys(data)) {
		if (key.charCodeAt(0) === 95 /* `_` */ && !keys.includes(key)) continue;
		out[key] = (data as Record<string, unknown>)[key];
	}
	return out as T;
}

function _matchesAllowedWrapKind(kind: string, allowedKinds: readonly string[]): boolean {
	if (allowedKinds.includes(kind)) return true;
	const stripped = kind.startsWith('_') ? kind.slice(1) : undefined;
	if (stripped && allowedKinds.includes(stripped)) return true;
	for (const allowed of allowedKinds) {
		const members =
			SUPERTYPE_MEMBERS[allowed] ?? SUPERTYPE_MEMBERS[allowed.startsWith('_') ? allowed.slice(1) : allowed];
		if (members?.has(kind)) return true;
		if (stripped !== undefined && members?.has(stripped)) return true;
		const allowedStripped = allowed.startsWith('_') ? allowed.slice(1) : allowed;
		if (allowedStripped === kind || (stripped !== undefined && allowedStripped === stripped)) return true;
	}
	return false;
}

// Kind-keyed child probe: the grammar-agnostic reader stores an
// unlabeled named child under `_<childKind>` (read_node.rs kind-named
// slots). A VISIBLE supertype occurrence (an enrich-minted alias like
// `alias($._expression_except_range, $.expression_group1)`) therefore
// carries its single member child as a kind-keyed property, NOT in
// `$other` — probe those keys before falling back to the `$other` scan.
function _firstKindKeyedWrapChild(data: object, allowedKinds: readonly string[]): unknown {
	for (const key of Object.keys(data)) {
		if (key.charCodeAt(0) !== 95 /* `_` */) continue;
		const stripped = key.slice(1);
		if (!_matchesAllowedWrapKind(stripped, allowedKinds) && !_matchesAllowedWrapKind(key, allowedKinds)) continue;
		const value = (data as Record<string, unknown>)[key];
		if (value !== undefined) return value;
	}
	return undefined;
}

function _filterWrapChildrenByKind<T>(value: readonly T[], allowedKinds: readonly string[]): readonly T[];
function _filterWrapChildrenByKind<T>(
	value: T | readonly T[] | undefined,
	allowedKinds: readonly string[]
): T | readonly T[] | undefined;
function _filterWrapChildrenByKind<T>(
	value: T | readonly T[] | undefined,
	allowedKinds: readonly string[]
): T | readonly T[] | undefined {
	if (value == null) return undefined;
	if (!Array.isArray(value)) {
		const kind = _wrapKindNameOf(value);
		if (kind === undefined) return value;
		return _matchesAllowedWrapKind(kind, allowedKinds) ? value : undefined;
	}
	const entries = value;
	return entries.filter((entry) => {
		// Text-collapsed leaf elements (e.g. identifiers rendered as their
		// $text string) survive the legacy readNode walker but carry no $type
		// to classify. Keep them — the field tag already selected the slot\u2019s
		// content. Numeric separator kind-ids stay dropped (the template\u2019s
		// join re-adds separators).
		if (typeof entry === 'string') return true;
		const kind = _wrapKindNameOf(entry);
		if (kind === undefined) return false;
		return _matchesAllowedWrapKind(kind, allowedKinds);
	});
}

// A wire delimiter is a field-tagged separator token: either its bare
// numeric kind id (text-collapsed contexts) or an anonymous node stub
// `{ $type: <id>, $named: false }` (node-stub contexts).
type _WireDelimiter = number | { readonly $type: number; readonly $named: false };
function _isWireDelimiter(e: unknown, separatorKindIds: readonly number[]): e is _WireDelimiter {
	if (typeof e === 'number') return separatorKindIds.includes(e);
	if (typeof e === 'object' && e !== null) {
		const stub = e as { $type?: unknown; $named?: unknown };
		return stub.$named === false && typeof stub.$type === 'number' && separatorKindIds.includes(stub.$type);
	}
	return false;
}

// A `many` slot with a separator fact whose separator the parser
// field-tagged into the slot: the render body re-joins the slot
// with its own separator, so the wire delimiter is dropped rather
// than stored.
// Assumes T itself is never an array type — slot elements are node unions.
function dropWireDelimiters<T>(
	value: T | readonly (T | _WireDelimiter)[] | undefined,
	separatorKindIds: readonly number[]
): T | readonly T[] | undefined {
	const isSlotList = (v: T | readonly (T | _WireDelimiter)[]): v is readonly (T | _WireDelimiter)[] => Array.isArray(v);
	if (value == null) return undefined;
	if (!isSlotList(value)) return _isWireDelimiter(value, separatorKindIds) ? undefined : value;
	return value.filter((e): e is T => !_isWireDelimiter(e, separatorKindIds));
}

export function wrapSourceFile(data: T.SourceFile, tree: TreeHandle) {
	data = _keepModelledSlots(data, ['_shebang', '_statements']);
	const _node = withMethods(
		{
			...data,
			$type: TSKindId.SourceFile as const,
			_shebang: normalizeSingularWrapSlot(data._shebang, 'shebang', false, data.$type, {
				tree,
				nodeType: data.$type,
				slotName: 'shebang',
				span: (data as _NodeData).$span
			}),
			_statements: projectMixedEnumStorage(
				normalizeRepeatedWrapSlot(data._statements, false, 'statements', {
					tree,
					nodeType: data.$type,
					slotName: 'statements',
					span: (data as _NodeData).$span
				}),
				{ ';': 173 }
			),

			shebang() {
				return drillIn<T.Shebang | undefined>(this._shebang, tree);
			},
			statements() {
				return drillInAll<T.ExpressionStatement | T.DeclarationStatement>(
					this._statements as readonly (T.ExpressionStatement | T.DeclarationStatement)[] | undefined,
					tree
				);
			},
			$with: {
				shebang: (v: NonNullable<T.SourceFile['_shebang']>) => wrapSourceFile({ ...$edited(data), _shebang: v }, tree),
				statements: (...v: NonNullable<T.SourceFile['_statements']>[number][]) =>
					wrapSourceFile({ ...$edited(data), _statements: v }, tree)
			}
		},
		_treeEngine(tree)
	);
	return _node;
}

export function wrapStatement(
	data: T.Statement & { readonly $other?: T.Statement | readonly T.Statement[] },
	tree: TreeHandle
) {
	if (typeof data === 'number') return data;
	const node = _keepModelledSlots(data, [
		'_expression_statement',
		'__declaration_statement',
		'_declaration_statement',
		'_const_item',
		'_macro_invocation',
		'_macro_definition',
		'_empty_statement',
		'_attribute_item',
		'_inner_attribute_item',
		'_mod_item',
		'_foreign_mod_item',
		'_struct_item',
		'_union_item',
		'_enum_item',
		'_type_item',
		'_function_item',
		'_function_signature_item',
		'_impl_item',
		'_trait_item',
		'_associated_type',
		'_let_declaration',
		'_use_declaration',
		'_extern_crate_declaration',
		'_static_item',
		'_macro_definition_paren',
		'_macro_definition_bracket',
		'_macro_definition_brace',
		'_mod_item_external',
		'_mod_item_inline',
		'_foreign_mod_item_semi',
		'_foreign_mod_item_body',
		'_struct_item_brace',
		'_struct_item_tuple',
		'_struct_item_unit',
		'_impl_item_body',
		'_impl_item_semi'
	]);
	const kindKeyed = _firstKindKeyedWrapChild(node, [
		'expression_statement',
		'_declaration_statement',
		'declaration_statement',
		'const_item',
		'macro_invocation',
		'macro_definition',
		'empty_statement',
		'attribute_item',
		'inner_attribute_item',
		'mod_item',
		'foreign_mod_item',
		'struct_item',
		'union_item',
		'enum_item',
		'type_item',
		'function_item',
		'function_signature_item',
		'impl_item',
		'trait_item',
		'associated_type',
		'let_declaration',
		'use_declaration',
		'extern_crate_declaration',
		'static_item',
		'macro_definition_paren',
		'macro_definition_bracket',
		'macro_definition_brace',
		'mod_item_external',
		'mod_item_inline',
		'foreign_mod_item_semi',
		'foreign_mod_item_body',
		'struct_item_brace',
		'struct_item_tuple',
		'struct_item_unit',
		'impl_item_body',
		'impl_item_semi'
	]) as T.Statement | readonly T.Statement[] | undefined;
	const filtered =
		kindKeyed ??
		_filterWrapChildrenByKind(node.$other, [
			'expression_statement',
			'_declaration_statement',
			'declaration_statement',
			'const_item',
			'macro_invocation',
			'macro_definition',
			'empty_statement',
			'attribute_item',
			'inner_attribute_item',
			'mod_item',
			'foreign_mod_item',
			'struct_item',
			'union_item',
			'enum_item',
			'type_item',
			'function_item',
			'function_signature_item',
			'impl_item',
			'trait_item',
			'associated_type',
			'let_declaration',
			'use_declaration',
			'extern_crate_declaration',
			'static_item',
			'macro_definition_paren',
			'macro_definition_bracket',
			'macro_definition_brace',
			'mod_item_external',
			'mod_item_inline',
			'foreign_mod_item_semi',
			'foreign_mod_item_body',
			'struct_item_brace',
			'struct_item_tuple',
			'struct_item_unit',
			'impl_item_body',
			'impl_item_semi'
		]);
	if (
		filtered === undefined &&
		(typeof (node as _NodeData).$text === 'string' || (node as _NodeData).$nodeHandle != null)
	) {
		return drillInSelf<T.Statement>(node as T.Statement, tree);
	}
	return drillIn<T.Statement>(
		normalizeSingularWrapSlot(filtered, 'children', true, node.$type, {
			tree,
			nodeType: node.$type,
			slotName: 'children',
			span: (node as _NodeData).$span
		}),
		tree
	);
}

