export function wrapUseClause(
	data: T.UseClause & { readonly $other?: T.UseClause | readonly T.UseClause[] },
	tree: TreeHandle
) {
	if (typeof data === 'number') return data;
	const node = _keepModelledSlots(data, [
		'_self',
		'_u8_keyword',
		'_i8_keyword',
		'_u16_keyword',
		'_i16_keyword',
		'_u32_keyword',
		'_i32_keyword',
		'_u64_keyword',
		'_i64_keyword',
		'_u128_keyword',
		'_i128_keyword',
		'_isize_keyword',
		'_usize_keyword',
		'_f32_keyword',
		'_f64_keyword',
		'_bool_keyword',
		'_str_keyword',
		'_char_keyword',
		'_metavariable',
		'_super',
		'_crate',
		'_identifier',
		'_scoped_identifier',
		'_default_keyword',
		'_union_keyword',
		'_gen_keyword',
		'_use_as_clause',
		'_use_list',
		'_scoped_use_list',
		'_use_wildcard'
	]);
	const kindKeyed = _firstKindKeyedWrapChild(node, [
		'self',
		'u8_keyword',
		'i8_keyword',
		'u16_keyword',
		'i16_keyword',
		'u32_keyword',
		'i32_keyword',
		'u64_keyword',
		'i64_keyword',
		'u128_keyword',
		'i128_keyword',
		'isize_keyword',
		'usize_keyword',
		'f32_keyword',
		'f64_keyword',
		'bool_keyword',
		'str_keyword',
		'char_keyword',
		'metavariable',
		'super',
		'crate',
		'identifier',
		'scoped_identifier',
		'default_keyword',
		'union_keyword',
		'gen_keyword',
		'use_as_clause',
		'use_list',
		'scoped_use_list',
		'use_wildcard'
	]) as T.UseClause | readonly T.UseClause[] | undefined;
	const filtered =
		kindKeyed ??
		_filterWrapChildrenByKind(node.$other, [
			'self',
			'u8_keyword',
			'i8_keyword',
			'u16_keyword',
			'i16_keyword',
			'u32_keyword',
			'i32_keyword',
			'u64_keyword',
			'i64_keyword',
			'u128_keyword',
			'i128_keyword',
			'isize_keyword',
			'usize_keyword',
			'f32_keyword',
			'f64_keyword',
			'bool_keyword',
			'str_keyword',
			'char_keyword',
			'metavariable',
			'super',
			'crate',
			'identifier',
			'scoped_identifier',
			'default_keyword',
			'union_keyword',
			'gen_keyword',
			'use_as_clause',
			'use_list',
			'scoped_use_list',
			'use_wildcard'
		]);
	if (
		filtered === undefined &&
		(typeof (node as _NodeData).$text === 'string' || (node as _NodeData).$nodeHandle != null)
	) {
		return drillInSelf<T.UseClause>(node as T.UseClause, tree);
	}
	return drillIn<T.UseClause>(
		normalizeSingularWrapSlot(filtered, 'children', true, node.$type, {
			tree,
			nodeType: node.$type,
			slotName: 'children',
			span: (node as _NodeData).$span
		}),
		tree
	);
}

